flowchart TD
  S[Server is slow] --> D{Disk full?}
  D -->|yes| D1[Find big files with du, clean up]
  D -->|no| M{Memory low?}
  M -->|yes| M1[Find the heavy process with top]
  M -->|no| C{CPU busy?}
  C -->|yes| C1[Identify the process, restart or fix]
  C -->|no| N[Check network and logs]

{
  "name": "ci-demo",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": { "test": "node --test", "build": "node build.js" }
}

import test from 'node:test';
import assert from 'node:assert';
import { sum } from '../sum.js';

test('adds two numbers', () => assert.equal(sum(2, 3), 5));
test('works with negatives', () => assert.equal(sum(-2, 1), -1));

import { mkdirSync, writeFileSync } from 'node:fs';
mkdirSync('dist', { recursive: true });
writeFileSync('dist/build-info.txt', 'built ok\n');
console.log('build finished');
